public void processPayment(User user, PaymentRequest request) {
    // Unleash client evaluation
    if (unleash.isEnabled("enable-new-payment-gateway", new UnleashContext(user.getId()))) {
        gatewayService.processViaNewProvider(request);
    } else {
        gatewayService.processViaLegacyProvider(request);
    }
}
